{"entry_id": 968952, "headword": "العُرْشُ", "headword_bare": "العرش", "headword_norm": "العرش", "root": "عرش", "root_source": "camel", "pos": null, "definitions_text": "العُرْشُ:\nبضم أوله، وسكون ثانيه، وآخره شين معجمة، وقد يضم ثانيه، وهو جمع عريش، وهي مظالّ تسوّى من جريد النخل ويطرح فوقها الثمام، ثم تجمع عروشا جمع الجمع، وقيل: العرش اسم لمكة نفسها، والظاهر أن مكة سميت بذلك لكثرة العرش بها، ومنه حديث عمر: أنه كان يقطع التلبية إذا نظر إلى عرش مكة، يعني بيوت أهل الحاجة منهم، ومنه حديث سعد: تمتعنا مع رسول الله، صلّى الله عليه وسلّم، ومعاوية كافر بالعرش، يعني وهو مقيم بعرش مكة، وهي بيوتها، في حال كفره، والعرش: مدينة باليمن على الساحل.", "translation_en": null, "translation_fr": null, "domain": null, "dict_name_ar": "معجم البلدان لياقوت الحموي", "dict_name_en": "Yāqūt al-Ḥamawī, Muʿjam al-Buldān (d. 1229)", "dict_source_type": "hawramani", "dict_period": "classical"}
{"entry_id": 799835, "headword": "العَرْشُ", "headword_bare": "العرش", "headword_norm": "العرش", "root": "عرش", "root_source": "camel", "pos": null, "definitions_text": "العَرْشُ: عَرْشُ اللهِ تعالى، ولا يُحَدُّ، أو ياقوتٌ أحْمَرُ يَتَلأَلَأ من نورِ الجَبَّارِ تعالى، وسَرِيرُ المَلِكِ، والعِزُّ، وقِوامُ الأمرِ، ومنه: ثُلَّ عَرْشُه، ورُكْنُ الشيءِ،وـ من البيتِ: سَقْفُه، والخَيْمَةُ، والبيتُ الذي يُسْتَظَل به،كالعَرِيشِ ج: عُروشٌ وعُرُشٌ وأعْراشٌ وعِرَشَةٌ،وـ من القومِ: رَئيسُهُم المُدَبِّرُ لأمرِهِمْ، والقَصْرُ، وأربعةُ كَواكِبَ صِغارٌ أسْفَلَ من العَوَّاءِ، ويقالُ لها: عَرْشُ السِمَاكِ، وعَجُزُ الأسَدِ، والجَنَازَةُ، قيل: ومنه:\"اهْتَزَّ العَرْشُ لموتِ سَعْدِ بنِ مُعاذٍ\" واهْتِزَازهُ: فَرَحُهُ، والمُلْكُ، والخَشَبُ تُطْوَى به البئْرُ بعدَ أن تُطْوَى بالحِجَارَةِ قَدْرَ قامَةٍ،وـ من القَدَمِ: ما نَتَأ من ظَهْرِ القَدَمِ، والمَظَلَّةُ، وأكثرُ ما يكونُ من القَصَبِ، والخَشَبُ الذي يقومُ عليه المُسْتَقِي،وـ للطائِرِ: عُشُّهُ، وبالضم: لَحْمَتَانِ مُسْتَطِيلَتَانِ في ناحِيَتِي العُنُقِ، أو في أصْلِهَا، أو مَوْضِعا المِحْجَمَتَيْنِ، وعَظْمَانِ في اللَّهاةِ يُقيمانِ اللسانَ، وآخِرُ شَعَرِ العُرْفِ من الفَرَسِ، والأُذُنُ، والضَّخْمَةُ من النُّوقِ، كأنَّها مَعْروشةُ الزَّوْرِ، ومكةُ، أو بُيوتُها القديمةُ، ويُفْتَحُ، أو بالفتحِ: مكةُ،كالعَرِيشِ، وبالضم: بُيوتُها،كالعُروشِ، وما بينَ العَيْرِ والأصابعِ من ظَهْرِ القَدَمِ، ويُفْتَحُج: عِرَشَةٌ وأعْراشٌ. وقولُ سَعْدٍ: وفلانٌ كافِرٌ بالعُرُشِ، يعني مُعَاوِيَةَ مُقيمٌ بمكةَ.وبَعيرٌ مَعْروشُ الجَنْبَيْنِ: عَظيمُهُما.وعُرِشَ الوَقودُ وعُرِّشَ، مَجْهُولَيْنِ: أُوقِدَ، وأُديمَ.والعَريشُ: كالهَوْدَجِ، وما عُرِّشَ للكَرْمِ، وخَيْمَةٌ من خَشَبٍ وثُمَامٍج: عُرُشٌ،ود من أعْمالِ مِصْرَ خَرِبَتْ، وأنْ يكونَ في الأصْلِ الواحِدِ أرْبَعُ نَخَلاتٍ أو خَمْسٌ.وعَرَشَ يَعْرِشُ ويَعْرُشُ: بَنَى عَريشاً،كأعْرَشَ وعَرَّشَ،وـ الكَلْبُ: خَرِق، ولم يَدْنُ للصيْدِ،وـ الرَّجُلُ: بَطِرَ، وبُهِتَ،كعَرِشَ، بالكسر، عَرْشاً وعَرَشاً،وـ البَيْتَ: بناهُ،وـ الكَرْمَ عَرْشاً وعُروشاً: رَفَعَ دوالِيَهُ على الخَشَبِ،كعَرَّشَهُ،وـ البِئْرَ: طَوَاهَا بالحِجَارَةِ قَدْرَ قامَةٍ من أسْفَلِهَا وسائِرُهَا بالخَشَبِ،وـ فلاناً: ضَرَبَهُ في عُرْشِ رَقَبَتِهِ،وـ بالمكانِ: أقامَ.وعَرِشَ بغَرِيمِهِ، كسَمِعَ: لَزِمَهُ،وـ عَنِّي: عَدَلَ.وـ عَلَيَّ ما عِنْدَ فلانٍ: امْتَنَعَ.وعَرَّشَ الحِمَارُ برأسِهِ تَعْرِيشاً: حُمِلَ عليه، فَرَفَعَ رأسَهُ وشَحا فاه،وـ البَيْتَ: سَقَفَهُ،وـ الأمْرَ: أبْطَأ به.وتَعَرَّشَ بالبَلَدِ: ثَبَتَ،وـ بالأمْرِ: تَعَلَّقَ،كتَعَرْوَشَ.واعْتَرَشَ العِنَبُ: عَلاَ على العريشِ،وـ فلانٌ: اتَّخَذَ عَريشاً،وـ الدابَّةَ: رَكِبَها، كاعْتَرَسَهَاواعْرَوَّشَها وتَعَرْوَشَها.والمُعَرْوِشُ: المُسْتَظِلُّ بِشَجَرَةٍ ونحوِها.", "translation_en": null, "translation_fr": null, "domain": null, "dict_name_ar": "القاموس المحيط للفيروزآبادي", "dict_name_en": "Firuzabadi, al-Qāmūs al-Muḥīṭ (d. 1414 CE)", "dict_source_type": "hawramani", "dict_period": "classical"}
{"entry_id": 814429, "headword": "العرش", "headword_bare": "العرش", "headword_norm": "العرش", "root": "عرش", "root_source": "camel", "pos": null, "definitions_text": "العرش: كالعريش، ما أقيم من البناء على حالة عجالة يدفع سورة الحر والبرد، ولا يدفع جملتها.", "translation_en": null, "translation_fr": null, "domain": null, "dict_name_ar": "التوقيف على مهمات التعاريف للمناوي", "dict_name_en": "Al-Munāwī, al-Tawqīf ʿalā Muhimmāt al-Taʿārīf (d. 1622 CE)", "dict_source_type": "hawramani", "dict_period": "classical"}
{"entry_id": 814430, "headword": "العرش", "headword_bare": "العرش", "headword_norm": "العرش", "root": "عرش", "root_source": "camel", "pos": null, "definitions_text": "العرش: الجسم المحيط بجميع الأجسام سمي به لارتفاعه أو للتشبيه بسرير الملك في تمكنه عليه عند الحكم لنزول أحكام قضائه وقدره منه. ولا صورة ولا جسم ثم، ذكره ابن الكمال. وقال الراغب: عرش الله ما لا يعلمه البشر إلا بالاسم وليس كما تذهب أوهام العامة إذ لو كان كذلك كان حاملا معه تعالى عن ذلك، لا محمولا، والله يقول {إِنَّ اللَّهَ يُمْسِكُ السَّمَاوَات} . الآية.", "translation_en": null, "translation_fr": null, "domain": null, "dict_name_ar": "التوقيف على مهمات التعاريف للمناوي", "dict_name_en": "Al-Munāwī, al-Tawqīf ʿalā Muhimmāt al-Taʿārīf (d. 1622 CE)", "dict_source_type": "hawramani", "dict_period": "classical"}
{"entry_id": 820192, "headword": "العرش", "headword_bare": "العرش", "headword_norm": "العرش", "root": "عرش", "root_source": "camel", "pos": null, "definitions_text": "العرش:[في الانكليزية] Throne [ في الفرنسية] Trone بالفتح وسكون الراء المهملة في لسان أهل الشرع هو الذي سمّاه الحكماء فلك الأفلاك. والعرش الأكبر عند الصوفية قلب الإنسان الكامل كما في كشف اللغات.", "translation_en": null, "translation_fr": null, "domain": null, "dict_name_ar": "كشّاف اصطلاحات الفنون والعلوم للتهانوي", "dict_name_en": "Al-Tahānawī, Kashshāf Iṣṭilāḥāt al-Funūn wa-l-ʿUlūm (d. 1777 CE)", "dict_source_type": "hawramani", "dict_period": "classical"}
{"entry_id": 910704, "headword": "العَرْش", "headword_bare": "العرش", "headword_norm": "العرش", "root": "عرش", "root_source": "camel", "pos": null, "definitions_text": "العَرْش{خاويةٌ على عروشها}  أي سقوفها.العرش: السرير المُظِلّ، سرير الملك. قائم على العرش: أي ملك. مستوٍ على العرش: حاكم على الملك بالاستقلال . قال تعالى: {إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ} أي: بترتيب خاص، وإفاضة الخلق حسب استعداد. {ثُمَّ اسْتَوَى عَلَى الْعَرْشِ يُدَبِّرُ الْأَمْرَ مَا مِنْ شَفِيعٍ إِلَّا مِنْ بَعْدِ إِذْنِهِ ذَلِكُمُ اللَّهُ رَبُّكُمْ فَاعْبُدُوهُ أَفَلَا تَذَكَّرُونَ} .أي: بيده التدبير التامّ لثبوت تمام القدرة بالخلق، وتمام التدبير لرعاية الآجال والاستعداد. فلا قدرة لأحد إلا بإذنه. فلا عبودية لغيره، لكون الجميع تحت قدرته وتدبيره. فمن تذكر أول الأمور وجعلها أساس النظر أبطل الشركاءَ.", "translation_en": null, "translation_fr": null, "domain": null, "dict_name_ar": "مفردات القرآن للفراهي", "dict_name_en": "Hamiduddin Farahi, Mufradāt al-Qurʾān (d. 1930 CE)", "dict_source_type": "hawramani", "dict_period": "modern"}
{"entry_id": 877886, "headword": "الْعَرْش", "headword_bare": "العرش", "headword_norm": "العرش", "root": "عرش", "root_source": "camel", "pos": null, "definitions_text": "(الْعَرْش) الْملك وسرير الْملك وَفِي التَّنْزِيل الْعَزِيز {وَلها عرش عَظِيم} وقوام الْأَمر يُقَال اسْتَوَى الْملك على عَرْشه ملك وثل عَرْشه وهى أمره وَذهب عزه والسقف والمظلة وَأكْثر مَا تكون من الْقصب وَمَا يدعم بِهِ الْكَرم من خشب ليقوم عَلَيْهِ وتسترسل عَلَيْهِ أغصانه وَظهر الْقدَم وعرش الْقَوْم رئيسهم الْمُدبر لأمورهم وعرش الطَّائِر عشه (ج) عروش وأعراش\n(الْعَرْش) آخر شعر الْعرف من الْفرس وَالْأُذن يُقَال نفث فِي عرشيه أسر إِلَيْهِ وعرشا الْعُنُق لحمتان مستطيلتان فِي ناحيتيه بَينهمَا الفقار (ج) أعراش", "translation_en": null, "translation_fr": null, "domain": null, "dict_name_ar": "المعجم الوسيط لمجموعة من المؤلفين", "dict_name_en": "Academy of the Arabic Language in Cairo, al-Muʿjam al-Wasīṭ (1998)", "dict_source_type": "hawramani", "dict_period": "modern"}
{"entry_id": 817063, "headword": "الْعَرْش", "headword_bare": "العرش", "headword_norm": "العرش", "root": "عرش", "root_source": "camel", "pos": null, "definitions_text": "الْعَرْش: الْجِسْم الْمُحِيط بِجَمِيعِ الْأَجْسَام سمي بِهِ لارتفاعه أَو للتشبيه بسرير الْملك فِي تمكنه عَلَيْهِ عِنْد الحكم لنزول أَحْكَام قَضَائِهِ وَقدره مِنْهُ.", "translation_en": null, "translation_fr": null, "domain": null, "dict_name_ar": "دستور العلماء للأحمدنكري", "dict_name_en": "Aḥmadnagarī, Dastūr al-ʿUlamāʾ, or Jāmiʿ al-ʿUlūm fī Iṣṭilāḥāt al-Funūn (d. 18th Century CE)", "dict_source_type": "hawramani", "dict_period": "classical"}
{"entry_id": 18569, "headword": "العَرْشُ", "headword_bare": "العرش", "headword_norm": "العرش", "root": "عرش", "root_source": "ocr", "pos": "noun", "definitions_text": "المُلْكُ سريرُ المَلِكِ قِوَامُ الأمر؛ يقال: استوى الملك على عَرشِهِ: مَلكَ. وثُلَّ عَرْشُهُ: وهَى أَمْرُه وذهب عزُّه السَّقْف المظلَّة, وأكثرُ ما تكونُ من القصب ما يُدْعَمُ به الكرْمُ من خشب ليقومَ عليه وتسترسلَ عليه أغصانُه ظهرُ القدم عرْشُ القوم: رئيسهم المدبِّرُ لأمورِهم عرْشُ الطائر: عُشُّهُ", "translation_en": null, "translation_fr": null, "domain": null, "dict_name_ar": "المعجم الوسيط", "dict_name_en": "Al-Mu'jam Al-Wasit", "dict_source_type": "ocr", "dict_period": "modern"}
